import { inject, type InjectionKey } from 'vue';
import type { Props as ButtonProps } from '../button/Button.vue';

export type SplitButtonSize = Exclude<
  NonNullable<ButtonProps['size']>,
  'icon-sm' | 'icon-md' | 'icon-lg'
>;
export type SplitButtonVariant = Exclude<NonNullable<ButtonProps['variant']>, 'link'>;
type SplitButtonContextValue = { size: () => SplitButtonSize; variant: () => SplitButtonVariant };
export const SplitButtonContextKey: InjectionKey<SplitButtonContextValue> =
  Symbol('SplitButtonContext');
export const useSplitButtonContext = (componentName: string) => {
  const context = inject(SplitButtonContextKey);
  if (!context) throw new Error(`${componentName} must be used within SplitButton.`);
  return context;
};

export { default as SplitButton } from './SplitButton.vue';
export { default as SplitButtonAction } from './SplitButtonAction.vue';
export { default as SplitButtonTrigger } from './SplitButtonTrigger.vue';
export { default as SplitButtonPositioner } from './SplitButtonPositioner.vue';
export { default as SplitButtonContent } from './SplitButtonContent.vue';

import { cva } from 'class-variance-authority';

export const splitButtonTriggerVariants = cva(
  "relative min-w-0 ms-[calc(var(--moduix-button-border-width,var(--moduix-border-width-sm))*-1)] rounded-s-none motion-safe:[&:not([data-variant='link']):active]:[translate:none] before:pointer-events-none before:absolute before:inset-y-1.5 before:start-0 before:w-px before:bg-current before:opacity-[0.16] before:content-['']",
  {
    variants: {
      size: {
        xs: 'px-2',
        sm: 'px-2.5',
        md: 'px-3',
        lg: 'px-3.5',
        xl: 'px-4',
      },
      variant: {
        default: '',
        outline: 'before:opacity-0',
        secondary: '',
        destructive: '',
        'destructive-outline': 'before:opacity-0',
        ghost: '',
      },
    },
    defaultVariants: {
      size: 'md',
      variant: 'default',
    },
  },
);
